    if selected:
        first, last = selected
        headers.update(
            {
                "Content-Length": str(last - first + 1),
                "Content-Range": f"bytes {first}-{last}/{size}",
            }
        )

    def stream():
        try:
            while chunk := body.read(256 * 1024):
                yield chunk
        finally:
            body.close()

    return MediaResponse(
        stream(),
        status_code=206 if selected else 200,
        headers=headers,
        s3_body=body,
    )

