const { chromium } = require('playwright-core');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const base = 'http://localhost:8080';
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox','--disable-dev-shm-usage'] });
  const context = await browser.newContext();
  const result = { checks: [], unexpectedApiErrors: [] };
  const check = name => { result.checks.push(name); console.log('PASS ' + name); };
  try {
    const get = async path => {
      const response = await context.request.get(base + path);
      assert.equal(response.status(), 200, path);
      return response.json();
    };
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    page.on('response', r => { if (r.url().includes('/api/') && r.status() >= 500) result.unexpectedApiErrors.push(r.status()); });
    await page.goto(base + '/');
    await page.locator('.video-card').first().waitFor();
    assert(await page.locator('.topbar').isVisible());
    check('Frontend renders current production assets');
    const schema = await get('/openapi.json');
    const required = {
      '/api/videos/{video_id}': ['get','delete'],
      '/api/videos/{video_id}/comments': ['get','post'],
      '/api/videos/{video_id}/comments/{comment_id}/replies': ['get'],
      '/api/videos/{video_id}/comments/{comment_id}/like': ['put','delete'],
      '/api/videos/{video_id}/views': ['post'],
      '/api/videos/{video_id}/views/{session_id}': ['post'],
    };
    for (const [path,methods] of Object.entries(required)) for (const method of methods) assert(schema.paths[path]?.[method], method+' '+path);
    check('OpenAPI includes deletion, comment threads/likes and view endpoints');
    const feed = await get('/api/videos?limit=100');
    assert(feed.items.length > 0);
    const video = feed.items[0];
    result.videoId = video.id;
    const metadata = await get('/api/videos/' + video.id);
    assert.equal(typeof metadata.views_count, 'number');
    const roots = await get(`/api/videos/${video.id}/comments`);
    if (roots.items.length) {
      const comment = roots.items[0];
      assert.equal(typeof comment.likes_count, 'number');
      assert.equal(typeof comment.replies_count, 'number');
      await get(`/api/videos/${video.id}/comments/${comment.id}/replies`);
    }
    check('Read-only video/comment APIs and view counters');
    // Dependency checks reject these guest requests before reaching mutations.
    for (const [path,method] of [
      [`/api/videos/${video.id}`,'delete'],
      [`/api/videos/${video.id}/like`,'put'],
      [`/api/videos/${video.id}/comments`,'post'],
      [`/api/videos/${video.id}/comments/${video.id}/like`,'put'],
    ]) {
      const response = await context.request.fetch(base+path, {method,headers:{Origin:base},data:method==='post'?{body:'readonly access check'}:undefined});
      assert.equal(response.status(),401,path);
    }
    // Invalid origin must reject analytics before any view session can be created.
    const refused = await context.request.post(base+`/api/videos/${video.id}/views`,{headers:{Origin:'http://invalid.example'},data:{}});
    assert.equal(refused.status(),403);
    check('Guest writes denied; invalid-Origin views denied without writes');
    const mediaUrl = `/api/videos/${video.id}/media`;
    const range = await context.request.get(base+mediaUrl,{headers:{Range:'bytes=0-31'}});
    assert.equal(range.status(),206); assert.equal((await range.body()).length,32);
    const thumb = await context.request.get(base+`/api/videos/${video.id}/thumbnail`);
    assert.equal(thumb.status(),200);
    assert((await thumb.body()).subarray(0,2).equals(Buffer.from([255,216])));
    // Native media on a blank page: no app JS and no analytics POSTs.
    const playback = await context.newPage();
    const requests=[]; const ranges=[];
    playback.on('request',r=>requests.push(r.method()));
    playback.on('response',r=>{if(r.url().endsWith('/media'))ranges.push(r.status());});
    playback.on('pageerror',e=>errors.push(e.message));
    await playback.setContent('<video controls muted></video>');
    await playback.locator('video').evaluate((v,url)=>{v.src=url;v.muted=true;},base+mediaUrl);
    await playback.waitForFunction(()=>document.querySelector('video').readyState>=2);
    await playback.locator('video').evaluate(v=>v.play());
    await playback.waitForFunction(()=>document.querySelector('video').currentTime>1);
    result.playbackTime = await playback.locator('video').evaluate(v=>{v.pause();return v.currentTime;});
    assert(ranges.includes(206)); assert(requests.every(method=>method==='GET'));
    assert.equal((await get('/api/videos/'+video.id)).views_count,metadata.views_count);
    assert.deepEqual(errors,[]); assert.deepEqual(result.unexpectedApiErrors,[]);
    check('Existing MP4 plays in Chromium, HTTP 206; views_count unchanged');
    console.log('RESULT_JSON ' + JSON.stringify(result));
  } finally { await browser.close(); }
})().catch(e=>{console.error(e);process.exitCode=1;});

